-- CAREEROS P3-T04: billing core (phase plan D1, D9). The CREATE TABLE, index and CHECK statements are generated by
-- drizzle-kit; everything else is written by hand, following P3-T01. Runs as the migration (owner) role. Down migration:
-- down.sql in this folder.
--> statement-breakpoint
CREATE TABLE "billing_event" (
	"id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,
	"provider" text NOT NULL,
	"provider_event_id" text NOT NULL,
	"organization_id" text,
	"type" text NOT NULL,
	"received_at" timestamp with time zone DEFAULT now() NOT NULL,
	"processed_at" timestamp with time zone,
	"outcome" text NOT NULL,
	"error" text,
	CONSTRAINT "billing_event_outcome_check" CHECK ("outcome" in ('applied', 'duplicate', 'ignored', 'error'))
);
--> statement-breakpoint
CREATE UNIQUE INDEX "billing_event_provider_event_key" ON "billing_event" ("provider","provider_event_id");--> statement-breakpoint
CREATE INDEX "billing_event_org_received_idx" ON "billing_event" ("organization_id","received_at" DESC NULLS LAST);--> statement-breakpoint
ALTER TABLE "subscription" DROP CONSTRAINT "subscription_provider_check", ADD CONSTRAINT "subscription_provider_check" CHECK ("provider" in ('none', 'manual', 'paystack', 'stripe', 'mpesa', 'fake'));--> statement-breakpoint
-- 1. billing_event: every provider event that was verified, once. Global (no tenant data; the organization id only names
-- the organization the verified metadata pointed at, and is not a foreign key so an event for a deleted organization can
-- still be recorded). The app role has NO privilege and NO policy here, so it can neither read nor write the table
-- directly; the definer functions below are the only way in. The REVOKE is repeated in infra/db/bootstrap-roles.sql
-- because that script's blanket GRANT would undo it.
ALTER TABLE "billing_event" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "billing_event" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS "owner_access" ON "billing_event";--> statement-breakpoint
CREATE POLICY "owner_access" ON "billing_event" TO CURRENT_USER USING (true) WITH CHECK (true);--> statement-breakpoint
DO $$ BEGIN
	IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'careeros_app') THEN
		REVOKE ALL ON TABLE public.billing_event FROM careeros_app;
	END IF;
END $$;--> statement-breakpoint
COMMENT ON COLUMN "billing_event"."error" IS 'The failure text of an error row, or the reason an ignored event changed nothing. Never a payload.';--> statement-breakpoint
-- 2. careeros_record_billing_event: records one verified event and answers whether it is NEW. The unique key
-- (provider, provider_event_id) makes a repeated event a duplicate: nothing is written and false is returned, so the
-- caller stops. A row left by a failed attempt (outcome 'error') is replaced, so the provider's retry is processed.
-- Callers run it inside the transaction that applies the event, so a rolled-back event leaves no 'applied' row.
CREATE OR REPLACE FUNCTION public.careeros_record_billing_event(
	p_provider text, p_provider_event_id text, p_organization_id text, p_type text, p_outcome text, p_error text
) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	fresh boolean;
BEGIN
	IF p_provider IS NULL OR p_provider !~ '^[a-z][a-z0-9_]{1,31}$' THEN
		RAISE EXCEPTION 'careeros_record_billing_event: invalid provider';
	END IF;
	IF p_provider_event_id IS NULL OR p_provider_event_id !~ '^[A-Za-z0-9_.:-]{1,200}$' THEN
		RAISE EXCEPTION 'careeros_record_billing_event: invalid provider event id';
	END IF;
	IF p_type IS NULL OR p_type !~ '^[a-z][a-z0-9_.]{1,63}$' THEN
		RAISE EXCEPTION 'careeros_record_billing_event: invalid type';
	END IF;
	IF p_outcome IS NULL OR p_outcome NOT IN ('applied', 'ignored', 'error') THEN
		RAISE EXCEPTION 'careeros_record_billing_event: outcome must be applied, ignored or error';
	END IF;
	INSERT INTO public.billing_event (provider, provider_event_id, organization_id, type, outcome, error, processed_at)
	VALUES (p_provider, p_provider_event_id, p_organization_id, p_type, p_outcome, left(p_error, 500), now())
	ON CONFLICT (provider, provider_event_id) DO UPDATE SET
		organization_id = excluded.organization_id, type = excluded.type, outcome = excluded.outcome,
		error = excluded.error, received_at = now(), processed_at = now()
		WHERE public.billing_event.outcome = 'error'
	RETURNING true INTO fresh;
	RETURN coalesce(fresh, false);
END
$$;--> statement-breakpoint
-- 3. careeros_billing_due_orgs: the ids of organizations the billing job should look at, nothing else (the scheduler has
-- no organization and row-level security hides every subscription from it). The job re-reads each organization under its
-- lock before changing anything, so this list may be generous.
CREATE OR REPLACE FUNCTION public.careeros_billing_due_orgs(p_now timestamptz) RETURNS TABLE (organization_id text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
	SELECT o.id FROM public.organization o JOIN public.subscription s ON s.organization_id = o.id
	WHERE o.status <> 'suspended' AND (
		(o.status = 'trial' AND s.trial_ends_at <= p_now)
		OR (o.status = 'past_due' AND s.grace_ends_at <= p_now)
		OR (s.status = 'canceled' AND coalesce(s.current_period_end, p_now) <= p_now)
	)
	ORDER BY o.id LIMIT 500
$$;--> statement-breakpoint
-- 4. careeros_record_manual_payment: a platform admin records a payment received outside a provider (an institution that
-- pays by invoice). It applies the same transition as a `payment.succeeded` event (the TypeScript state machine in
-- packages/billing/src/state.ts; a test keeps the two equal) with provider `manual`, records the event as
-- (manual, manual:<org>:<reference>) so a reference is applied once, and writes an audit row. Returns true when applied,
-- false when the reference was recorded before. A period that ends before the one already held raises: an admin who
-- types an old period should be told, not silently ignored. It checks nothing about the CALLER: P3-T07 does.
CREATE OR REPLACE FUNCTION public.careeros_record_manual_payment(
	p_org_id text, p_plan_id text, p_seats integer, p_interval text, p_period_start timestamptz, p_period_end timestamptz,
	p_amount bigint, p_currency text, p_reference text, p_actor_user_id text
) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	org public.organization%ROWTYPE;
	sub public.subscription%ROWTYPE;
	fresh boolean;
	fields jsonb;
	members integer;
BEGIN
	IF p_actor_user_id IS NULL THEN
		RAISE EXCEPTION 'careeros_record_manual_payment: a manual payment is recorded by a person';
	END IF;
	IF p_reference IS NULL OR btrim(p_reference) = '' OR length(p_reference) > 128 OR p_reference !~ '^[A-Za-z0-9_.:/# -]+$' THEN
		RAISE EXCEPTION 'careeros_record_manual_payment: invalid reference';
	END IF;
	IF p_seats IS NULL OR p_seats < 1 THEN
		RAISE EXCEPTION 'careeros_record_manual_payment: seats must be at least 1';
	END IF;
	IF p_interval IS NULL OR p_interval NOT IN ('month', 'year') THEN
		RAISE EXCEPTION 'careeros_record_manual_payment: interval must be month or year';
	END IF;
	IF p_period_start IS NULL OR p_period_end IS NULL OR p_period_end <= p_period_start THEN
		RAISE EXCEPTION 'careeros_record_manual_payment: the period must end after it starts';
	END IF;
	IF p_amount IS NULL OR p_amount < 0 OR p_currency IS NULL OR p_currency !~ '^[A-Z]{3}$' THEN
		RAISE EXCEPTION 'careeros_record_manual_payment: invalid amount or currency';
	END IF;
	-- The same lock the TypeScript paths take first, so a manual payment and a provider event never interleave.
	PERFORM pg_advisory_xact_lock(hashtextextended('careeros_billing:' || p_org_id, 0));
	SELECT * INTO org FROM public.organization WHERE id = p_org_id FOR UPDATE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'careeros_record_manual_payment: unknown organization';
	END IF;
	SELECT * INTO sub FROM public.subscription WHERE organization_id = p_org_id FOR UPDATE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'careeros_record_manual_payment: no subscription for the organization';
	END IF;
	IF NOT EXISTS (SELECT 1 FROM public.plan WHERE id = p_plan_id) THEN
		RAISE EXCEPTION 'careeros_record_manual_payment: unknown plan %', p_plan_id;
	END IF;
	IF sub.current_period_end IS NOT NULL AND p_period_end < sub.current_period_end THEN
		RAISE EXCEPTION 'careeros_record_manual_payment: the period ends before the paid period already held';
	END IF;
	fresh := public.careeros_record_billing_event('manual', 'manual:' || p_org_id || ':' || p_reference, p_org_id, 'payment.succeeded', 'applied', NULL);
	IF NOT fresh THEN
		RETURN false;
	END IF;
	IF org.plan_id IS DISTINCT FROM p_plan_id OR org.status IS DISTINCT FROM 'active' THEN
		PERFORM public.careeros_set_org_plan(p_org_id, p_plan_id, 'active', p_actor_user_id, 'manual_payment');
	END IF;
	fields := jsonb_build_object(
		'provider', 'manual', 'status', 'active', 'seats', p_seats, 'billing_interval', p_interval,
		'current_period_start', p_period_start, 'current_period_end', p_period_end, 'grace_ends_at', NULL::text);
	IF sub.provider IS DISTINCT FROM 'manual' THEN
		fields := fields || jsonb_build_object('provider_customer_id', NULL::text, 'provider_subscription_id', NULL::text);
	END IF;
	PERFORM public.careeros_set_subscription(p_org_id, fields, p_actor_user_id, 'manual');
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
	VALUES (p_org_id, p_actor_user_id, 'billing.manual_payment', 'subscription', p_org_id, jsonb_build_object(
		'source', 'manual', 'reference', p_reference, 'amount', p_amount, 'currency', p_currency, 'planId', p_plan_id,
		'seats', p_seats, 'interval', p_interval, 'periodStart', p_period_start, 'periodEnd', p_period_end));
	SELECT count(*) INTO members FROM public.member WHERE organization_id = p_org_id;
	IF p_seats < members THEN
		INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
		VALUES (p_org_id, p_actor_user_id, 'billing.seats_below_members', 'subscription', p_org_id,
			jsonb_build_object('source', 'manual', 'seatsPaid', p_seats, 'members', members, 'membersKept', true));
	END IF;
	RETURN true;
END
$$;--> statement-breakpoint
DO $$ BEGIN
	REVOKE ALL ON FUNCTION public.careeros_record_billing_event(text, text, text, text, text, text) FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.careeros_billing_due_orgs(timestamptz) FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.careeros_record_manual_payment(text, text, integer, text, timestamptz, timestamptz, bigint, text, text, text) FROM PUBLIC;
	IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'careeros_app') THEN
		GRANT EXECUTE ON FUNCTION public.careeros_record_billing_event(text, text, text, text, text, text) TO careeros_app;
		GRANT EXECUTE ON FUNCTION public.careeros_billing_due_orgs(timestamptz) TO careeros_app;
		GRANT EXECUTE ON FUNCTION public.careeros_record_manual_payment(text, text, integer, text, timestamptz, timestamptz, bigint, text, text, text) TO careeros_app;
	END IF;
END $$;
